#include <deque>
#include <iostream>
#include <map>
#include <string>

struct Thread
{
    std::string name{};
    int priority{};
};

class Scheduler
{
public:
    void ready(const Thread& t) {}
    std::string next() { return "idle"; }

private:
    std::map<int, std::deque<Thread>, std::greater<int>> m_ready{};
};

int main()
{
    Scheduler s{};
    s.ready({"A", 8});
    std::cout << s.next() << '\n';
}
